UPDATE odin_task_processor
SET
    queue_max_capacity = #{maxCapacity},
    queue_min_capacity = #{minCapacity},
    queue_runtime_instance_capacity = #{runtimeCapacity}
WHERE guid = #{guid}

UPDATE odin_task_processor
SET enable = 1
WHERE guid = #{guid}

UPDATE odin_task_processor
SET enable = 0
WHERE guid = #{guid}
